import{_ as t,o as i,c as o,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"Testing Strategy & E2E Validation","description":"Outlines the end-to-end testing requirements for Sanjeev AI core features, specifically Cloud Video Rendering and Notifications.","frontmatter":{"isInternal":true,"type":"Specification","title":"Testing Strategy & E2E Validation","description":"Outlines the end-to-end testing requirements for Sanjeev AI core features, specifically Cloud Video Rendering and Notifications.","tags":["testing","e2e","playwright","jest","specification"]},"headers":[],"relativePath":"specs/testing_strategy.md","filePath":"specs/testing_strategy.md"}'),n={name:"specs/testing_strategy.md"};function s(a,e,l,d,c,u){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="sanjeev-ai-testing-strategy-e2e-validation" tabindex="-1">Sanjeev AI: Testing Strategy &amp; E2E Validation <a class="header-anchor" href="#sanjeev-ai-testing-strategy-e2e-validation" aria-label="Permalink to &quot;Sanjeev AI: Testing Strategy &amp; E2E Validation&quot;">​</a></h1><p>This document formally defines the testing strategy for core product features before they are implemented by the development team. All features must adhere to Test-Driven Development (TDD) principles.</p><h2 id="_1-cloud-video-rendering-hybrid-export" tabindex="-1">1. Cloud Video Rendering (Hybrid Export) <a class="header-anchor" href="#_1-cloud-video-rendering-hybrid-export" aria-label="Permalink to &quot;1. Cloud Video Rendering (Hybrid Export)&quot;">​</a></h2><p>The video rendering system has two tiers (Local Canvas vs Cloud FFmpeg). E2E tests must validate the user permissions, UI state, and backend logic.</p><h3 id="_1-1-frontend-e2e-tests-playwright" tabindex="-1">1.1 Frontend E2E Tests (Playwright) <a class="header-anchor" href="#_1-1-frontend-e2e-tests-playwright" aria-label="Permalink to &quot;1.1 Frontend E2E Tests (Playwright)&quot;">​</a></h3><ul><li><strong>Test Case 1: Standard User Restrictions</strong><ul><li><strong>Scenario:</strong> A user with <code>plan: &quot;free&quot;</code> opens the Export Modal.</li><li><strong>Expected Outcome:</strong> The &quot;Cloud Render&quot; toggle is visible but disabled/locked. Clicking it should trigger an upsell prompt. The resolution dropdown should only show standard options supported by the browser canvas.</li></ul></li><li><strong>Test Case 2: Premium User Options</strong><ul><li><strong>Scenario:</strong> A user with <code>plan: &quot;pro&quot;</code> opens the Export Modal.</li><li><strong>Expected Outcome:</strong> The user can freely toggle between &quot;Local Render&quot; and &quot;Cloud Render&quot;. When Cloud Render is selected, the resolution dropdown displays &quot;720p (Default)&quot; and &quot;1080p&quot;.</li></ul></li><li><strong>Test Case 3: Concurrent Render Locking</strong><ul><li><strong>Scenario:</strong> A user initiates a Local Render.</li><li><strong>Expected Outcome:</strong> The Export button and Cloud Render toggle are immediately disabled to prevent overlapping rendering jobs.</li></ul></li></ul><h3 id="_1-2-backend-unit-integration-tests-jest" tabindex="-1">1.2 Backend Unit/Integration Tests (Jest) <a class="header-anchor" href="#_1-2-backend-unit-integration-tests-jest" aria-label="Permalink to &quot;1.2 Backend Unit/Integration Tests (Jest)&quot;">​</a></h3><ul><li><strong>Test Case 1: Credit Validation</strong><ul><li><strong>Scenario:</strong> <code>requestCloudRender</code> is called by a premium user with <code>credits: 0</code>.</li><li><strong>Expected Outcome:</strong> The Cloud Function immediately throws an <code>unauthenticated</code> or <code>payment-required</code> HttpsError. No Cloud Run job is dispatched.</li></ul></li><li><strong>Test Case 2: Credit Deduction</strong><ul><li><strong>Scenario:</strong> <code>requestCloudRender</code> is called by a premium user with <code>credits: 10</code>.</li><li><strong>Expected Outcome:</strong> The Cloud Run job is dispatched successfully, and the user&#39;s credit balance is atomically decremented by the calculated cost.</li></ul></li><li><strong>Test Case 3: FFmpeg Stitching (Mocked Integration)</strong><ul><li><strong>Scenario:</strong> The Cloud Run job container executes the rendering script with a standard test manifest.</li><li><strong>Expected Outcome:</strong> The script successfully outputs an MP4 file, and validates that the output resolution strictly matches the requested 720p or 1080p parameter.</li></ul></li></ul><h2 id="_2-in-app-notification-system-global-inbox" tabindex="-1">2. In-App Notification System (Global Inbox) <a class="header-anchor" href="#_2-in-app-notification-system-global-inbox" aria-label="Permalink to &quot;2. In-App Notification System (Global Inbox)&quot;">​</a></h2><p>The notification system must accurately reflect asynchronous background tasks in real-time.</p><h3 id="_2-1-frontend-e2e-tests-playwright" tabindex="-1">2.1 Frontend E2E Tests (Playwright) <a class="header-anchor" href="#_2-1-frontend-e2e-tests-playwright" aria-label="Permalink to &quot;2.1 Frontend E2E Tests (Playwright)&quot;">​</a></h3><ul><li><strong>Test Case 1: Real-time Inbox Badge Updates</strong><ul><li><strong>Scenario:</strong> A new document is written to the user&#39;s <code>notifications</code> sub-collection by a background process.</li><li><strong>Expected Outcome:</strong> The notification bell icon in the <code>NavBar</code> immediately increments its unread count badge without requiring a page refresh.</li></ul></li><li><strong>Test Case 2: Reading Notifications</strong><ul><li><strong>Scenario:</strong> The user opens the notification drawer and clicks on an unread notification.</li><li><strong>Expected Outcome:</strong> The specific notification is marked as <code>read: true</code> in Firestore, the unread badge counter decrements, and the user is navigated to the <code>actionUrl</code> (e.g., the completed video URL).</li></ul></li><li><strong>Test Case 3: Edge Case - Failed Render Alerts</strong><ul><li><strong>Scenario:</strong> The Cloud Run engine crashes or times out.</li><li><strong>Expected Outcome:</strong> An &quot;error&quot; type notification is pushed to the inbox. The UI must render this notification with an appropriate error styling (e.g., red icon/text) to distinguish it from success messages.</li></ul></li></ul><h2 id="_3-url-state-persistence-batch-2" tabindex="-1">3. URL State Persistence (Batch 2) <a class="header-anchor" href="#_3-url-state-persistence-batch-2" aria-label="Permalink to &quot;3. URL State Persistence (Batch 2)&quot;">​</a></h2><p>The Studio must support deep linking and persist active project/script state across hard refreshes via React Router to prevent frustrating kick-backs to the home dashboard.</p><h3 id="_3-1-frontend-e2e-tests-playwright" tabindex="-1">3.1 Frontend E2E Tests (Playwright) <a class="header-anchor" href="#_3-1-frontend-e2e-tests-playwright" aria-label="Permalink to &quot;3.1 Frontend E2E Tests (Playwright)&quot;">​</a></h3><ul><li><strong>Test Case 1: Deep Link Navigation</strong><ul><li><strong>Scenario:</strong> A user navigates directly to <code>/studio/:projectId/:scriptId</code> via a bookmarked link or pasted URL.</li><li><strong>Expected Outcome:</strong> The application initializes the Studio directly, loading the correct project and script data without forcing a redirect to the dashboard.</li></ul></li><li><strong>Test Case 2: Hard Refresh State Retention</strong><ul><li><strong>Scenario:</strong> While actively editing a script in the Studio (<code>/studio/:projectId/:scriptId</code>), the user performs a hard browser refresh (Cmd/Ctrl + Shift + R).</li><li><strong>Expected Outcome:</strong> The Studio re-renders successfully and the exact same project and script remain active. The user is NOT kicked back to the dashboard.</li></ul></li><li><strong>Test Case 3: Invalid URL Parameters</strong><ul><li><strong>Scenario:</strong> A user navigates to a Studio URL with an invalid or non-existent <code>projectId</code> or <code>scriptId</code>.</li><li><strong>Expected Outcome:</strong> The application gracefully handles the error, showing a user-friendly &quot;Project/Script Not Found&quot; state or safely redirecting to the dashboard instead of crashing.</li></ul></li></ul>',16)])])}const p=t(n,[["render",s]]);export{h as __pageData,p as default};
